/**
 * @distilled.cloud/opnsense — OPNsense firewall API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from OPNsense's own
 * model XML + API controller PHP, mirrored under `specs/`). Everything else
 * in this folder is hand-written.
 *
 * One module per API controller in scope — `firewall_alias`,
 * `firewall_category`, `firewall_group`, `firewall_filter`,
 * `routing_settings`, `quagga_general`, `quagga_bgp`, `quagga_service` — see
 * the package README for what each one covers and what was left out.
 *
 * @example
 * ```ts
 * import * as Opnsense from "@distilled.cloud/opnsense";
 *
 * const alias = yield* Opnsense.Services.firewall_alias.addAlias({
 *   alias: { name: "homeflare_edge", type: "host", content: "10.20.10.1" },
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  OpnsenseProtocol,
  type OpnsenseOpError,
  type OpnsenseOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
